mapper.select:
SELECT id AS template_id, template_key, display_name AS name, description, enabled
FROM iam_permission_template
WHERE id = #{templateId}

SELECT id AS template_id, template_key, display_name AS name, description, enabled
FROM iam_permission_template
WHERE id > #{afterTemplateId}
ORDER BY id
LIMIT #{limit}

SELECT id AS version_id, template_id, version_number, status
FROM iam_permission_template_version
WHERE id = #{versionId}

SELECT permission.id AS permission_id, permission.permission_code, permission.display_name, permission.description, permission.enabled, (SELECT COUNT(*) FROM iam_template_permission link WHERE link.permission_id = permission.id) AS in_use_count FROM iam_permission permission WHERE permission.id > #{afterPermissionId}
AND (permission.permission_code LIKE CONCAT('%', #{keyword}, '%') OR permission.display_name LIKE CONCAT('%', #{keyword}, '%'))
AND permission.permission_code LIKE CONCAT(#{domain}, '.%')
ORDER BY permission.id LIMIT #{limit}
